def solve(g):
    h,w=len(g),len(g[0])
    bg=Counter(c for row in g for c in row).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    blocks=[]; noise=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[(i,j)]
                while q:
                    x,y=q.popleft()
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]==col:
                            seen[a][b]=True;q.append((a,b));comp.append((a,b))
                if len(comp)==1 and col!=bg: noise.append((i,j))
                elif len(comp)>1 and col!=bg: blocks.append((col,comp))
    out=[r[:] for r in g]
    for i,j in noise:
        for col,comp in blocks:
            rs=[a for a,b in comp]; cs=[b for a,b in comp]
            if min(rs)<=i<=max(rs) and min(cs)<=j<=max(cs):
                out[i][j]=col; break
        else:
            out[i][j]=bg
    return out

